import React, { useState } from 'react';

export default function KeyExample() {
  const [items, setItems] = useState([{ id: 1, text: 'Apple' }, { id: 2, text: 'Banana' }]);

  const addItemToTop = () => {
    // Adding an item to the top of the array
    setItems([{ id: Date.now(), text: 'New Fruit' }, ...items]);
  };

  return (
    <div>
      <button onClick={addItemToTop}>Add Fruit to Top</button>
      <ul>
        {items.map((item, index) => (
          // BAD: key={index}. If we add an item to the top, the indexes of Apple and Banana change! 
          // React's diffing algorithm will think Apple became New Fruit, Banana became Apple, etc.
          // GOOD: key={item.id}. React knows Apple and Banana just moved down, and only inserts 1 new DOM node.
          <li key={item.id}>{item.text}</li>
        ))}
      </ul>
    </div>
  );
}
